type Item = { id: string; price: number; qty: number };
function applyDiscount(order: { items: Item[]; total: number }, discount: number) {
  const discounted = order.items.map(i => ({ ...i, price: i.price * (1 - discount) }));
  order.items = discounted;
  order.total = order.items.reduce((s, it) => s + it.price * it.qty, 0);
}
const cart = { items: [{ id: "a", price: 10, qty: 1 }], total: 10 };
applyDiscount(cart, 0.5);
